// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 initialBalance, uint8 numCalls) public {
        numCalls = uint8(bound(numCalls, 1, 20));
        initialBalance = bound(initialBalance, 0, 100 ether);

        vm.deal(address(c), initialBalance);

        uint256 totalDeposited = 0;
        uint256 totalTransferred = 0;

        vm.warp(1000);

        for (uint8 i = 0; i < numCalls; i++) {
            address caller = address(uint160(uint256(keccak256(abi.encodePacked(i, block.timestamp)))));
            vm.deal(caller, 10 ether);

            vm.warp(block.timestamp + 2);

            vm.roll(block.number + 1);

            uint256 balanceBefore = address(c).balance;
            vm.prank(caller);
            (bool success, ) = address(c).call{value: 10 ether}("");
            require(success, "call failed");

            totalDeposited += 10 ether;

            if (block.number % 15 == 0) {
                totalTransferred += (balanceBefore + 10 ether);
            }
        }

        uint256 expectedBalance = initialBalance + totalDeposited - totalTransferred;
        assertTrue(address(c).balance == expectedBalance);
    }
}
